    # 1. Staged framing & AI boilerplate transitions
    t = t.replace('Rather than relying on hazardous acetonitrile, the mobile phase uses bio-ethanol and water (5:95, v/v).',
                  'Acetonitrile was replaced with an eco-conscious eluent combining bio-ethanol and water (5:95, v/v).')
